#include <iostream>
using namespace std;

const int V = 7;
int component[V];

void mark(int adj[][V], int u, int id) {
    component[u] = id;
    for (int v = 0; v < V; v++) {
        if (adj[u][v] == 1 && component[v] == 0) {
            mark(adj, v, id);
        }
    }
}

int main() {
    int adj[V][V] = {};
    int edges[5][2] = {{0, 1}, {1, 2}, {3, 4}, {5, 6}, {4, 3}};
    for (int k = 0; k < 5; k++) {
        adj[edges[k][0]][edges[k][1]] = 1;
        adj[edges[k][1]][edges[k][0]] = 1;
    }
    int count = 0;
    for (int u = 0; u < V; u++) {
        if (component[u] == 0) {
            count++;
            mark(adj, u, count);
        }
    }
    cout << count << " connected components" << endl;
    return 0;
}
